const response = $json;

const REQUIRED_FIELDS = [
  "created_at", "source_type", "platform", "source_url", "parsed_at",
  "published_at", "freshness_status", "entity_type", "company_name",
  "profile_name", "profile_url", "region", "service_type", "offer_text",
  "terms", "contact_public", "text_context", "detected_need",
  "competitor_strength", "lead_signal_score", "content_idea_score",
  "quality_score", "reason", "recommended_action", "status"
];

// ── find text block ──────────────────────────────────────────────────────────
let rawText;
try {
  const textItem = response.content.find(c => c.type === 'text');
  if (!textItem) throw new Error('No text block in response');
  rawText = textItem.text;
} catch(e) {
  return [{ json: {
    status: "skipped", quality_score: 1, lead_signal_score: 1,
    content_idea_score: 1, competitor_strength: 1,
    entity_type: "irrelevant", recommended_action: "ignore",
    freshness_status: "unknown",
    reason: "No text block: " + e.message,
    test_pass_basic: false, parse_method: "line_failed",
    raw_response_preview: JSON.stringify(response).substring(0, 500)
  }}];
}

// ── strip markdown fences ────────────────────────────────────────────────────
rawText = rawText.trim();
rawText = rawText.replace(/^```[a-z]*\r?\n?/, '').replace(/\r?\n?```$/, '').trim();

// ── parse KEY=VALUE lines ────────────────────────────────────────────────────
const lines = rawText.split(/\r?\n/);
const fieldMap = {};
for (const line of lines) {
  const eqIdx = line.indexOf('=');
  if (eqIdx < 1) continue;
  const key = line.substring(0, eqIdx).trim();
  const val = line.substring(eqIdx + 1).trim();
  if (REQUIRED_FIELDS.includes(key)) {
    fieldMap[key] = val;
  }
}

const foundCount = REQUIRED_FIELDS.filter(f => fieldMap[f] !== undefined).length;
if (foundCount < 5) {
  return [{ json: {
    status: "skipped", quality_score: 1, lead_signal_score: 1,
    content_idea_score: 1, competitor_strength: 1,
    entity_type: "irrelevant", recommended_action: "ignore",
    freshness_status: "unknown",
    reason: "Line protocol parse failed: only " + foundCount + " of 25 fields found",
    test_pass_basic: false, parse_method: "line_failed",
    raw_response_preview: rawText.substring(0, 500)
  }}];
}

// ── helpers ──────────────────────────────────────────────────────────────────
function clampInt(val, fallback) {
  const n = parseInt(val, 10);
  return isNaN(n) ? fallback : Math.min(Math.max(n, 1), 100);
}
function pickEnum(val, allowed, fallback) {
  return allowed.includes(val) ? val : fallback;
}

// ── build parsed object ──────────────────────────────────────────────────────
const parsed = {
  created_at:          fieldMap.created_at    || "",
  source_type:         fieldMap.source_type   || "",
  platform:            fieldMap.platform      || "",
  source_url:          fieldMap.source_url    || "",
  parsed_at:           fieldMap.parsed_at     || "",
  published_at:        fieldMap.published_at  || "",
  freshness_status:    pickEnum(fieldMap.freshness_status,   ["fresh","recent","old","unknown"],                                                          "unknown"),
  entity_type:         pickEnum(fieldMap.entity_type,        ["competitor","lead_signal","market_signal","content_idea","irrelevant"],                     "irrelevant"),
  company_name:        fieldMap.company_name  || "",
  profile_name:        fieldMap.profile_name  || "",
  profile_url:         fieldMap.profile_url   || "",
  region:              fieldMap.region        || "",
  service_type:        pickEnum(fieldMap.service_type,       ["secured_auto_loan","secured_real_estate_loan","pts_loan","refinancing","mortgage_adjacent","business_loan","generic_lending","unknown"], "unknown"),
  offer_text:          fieldMap.offer_text    || "",
  terms:               fieldMap.terms         || "",
  contact_public:      fieldMap.contact_public || "",
  text_context:        fieldMap.text_context  || "",
  detected_need:       fieldMap.detected_need || "",
  competitor_strength: clampInt(fieldMap.competitor_strength, 1),
  lead_signal_score:   clampInt(fieldMap.lead_signal_score,   1),
  content_idea_score:  clampInt(fieldMap.content_idea_score,  1),
  quality_score:       clampInt(fieldMap.quality_score,       1),
  reason:              fieldMap.reason        || "",
  recommended_action:  pickEnum(fieldMap.recommended_action,  ["monitor","contact","create_content","ignore","investigate"],                               "ignore"),
  status:              pickEnum(fieldMap.status,               ["analyzed","skipped"],                                                                     "skipped")
};

// ── pull test metadata ───────────────────────────────────────────────────────
let testMeta = {};
try {
  testMeta = $('Select Test Record').first().json;
} catch(e) {
  testMeta = { test_id: 0, expected_entity_type: "", expected_recommended_action: "", expected_quality_range: "" };
}

const actualQuality = parsed.quality_score;
const actualEntity  = parsed.entity_type;
const actualAction  = parsed.recommended_action;
const actualLead    = parsed.lead_signal_score;
const actualContent = parsed.content_idea_score;
const actualComp    = parsed.competitor_strength;

const entityMatch   = (actualEntity === (testMeta.expected_entity_type || ""));
const testPassBasic = entityMatch && (parsed.status !== undefined);

return [{ json: {
  ...parsed,
  test_id:                     testMeta.test_id || 0,
  expected_entity_type:        testMeta.expected_entity_type        || "",
  expected_recommended_action: testMeta.expected_recommended_action || "",
  expected_quality_range:      testMeta.expected_quality_range      || "",
  actual_entity_type:          actualEntity,
  actual_recommended_action:   actualAction,
  actual_quality_score:        actualQuality,
  actual_lead_signal_score:    actualLead,
  actual_content_idea_score:   actualContent,
  actual_competitor_strength:  actualComp,
  test_pass_basic:             testPassBasic,
  parse_method:                "line_protocol",
  test_notes: "parse=line_protocol"
    + "; fields=" + foundCount
    + "; entity_match=" + entityMatch
    + "; quality=" + actualQuality
    + "; action=" + actualAction
    + "; expected_action=" + (testMeta.expected_recommended_action || "")
}}];
